#include <bits/stdc++.h>
#define LL long long
#define REP(i, l, r) for (int i = l; i <= r; i++)
using namespace std;
const int P = 998244353, MOD = 1e9 + 7, B = 1e6;
int normalize(ll d) { return (d % P + P) % P; }
LL n_value, total_count, prefix_sum[7];
int result;
vector<int> sequences[7];

void build_sequences(int level, LL val) {
    total_count++;
    sequences[level].push_back(normalize(total_count - val));
    if (level < 6) REP(i, 0, 9) build_sequences(level + 1, val * 10 + i);
}

int get_value(int id, int f) {
    int pos = lower_bound(sequences[id].begin(), sequences[id].end(), P - f) - sequences[id].begin();
    return ((LL)f * sequences[id].size() + prefix_sum[id] - (LL)P * (sequences[id].size() - pos)) % MOD;
}

void traverse(int depth, LL v) {
    if (v > n_value) return;
    if (depth >= 1) {
        if (v * B > n_value / 10 && v * B + B - 1 <= n_value) {
            int t = 1;
            REP(i, 0, 6) (result += get_value(i, normalize(total_count - v * t))) %= MOD, t *= 10;
            REP(i, 0, 6) total_count += sequences[i].size();
            return;
        }
        result = (result + normalize(++total_count - v)) % MOD;
    }
    REP(i, !depth, 9) traverse(depth + 1, v * 10 + i);
}

int main() {
    scanf("%lld", &n_value);
    build_sequences(0, 0);
    REP(i, 0, 6) {
        sort(sequences[i].begin(), sequences[i].end());
        for (int j = 0; j < (int)sequences[i].size(); j++) prefix_sum[i] += sequences[i][j];
    }
    total_count = 0;
    traverse(0, 0);
    printf("%d\n", result);
    return 0;
}
